section.code:
/* The size of a results test field. */

#define RESULTS_VALUE_LEN 16

/* Line Data Structure */

struct results_data {
	char shape[RESULTS_VALUE_LEN];
	char sides[RESULTS_VALUE_LEN];
	char internal_angle[RESULTS_VALUE_LEN];
	char side_length[RESULTS_VALUE_LEN];
	char perimeter[RESULTS_VALUE_LEN];
	char area[RESULTS_VALUE_LEN];
};

/* Global Variables. */

static size_t results_row_count = 0;
static struct results_data results_rows[RESULTS_MAX_ROWS];

/* Store the current calculation data. */

void results_store_current_data(char *shape)
{
	if (results_row_count >= RESULTS_MAX_ROWS)
		return;

	string_copy(results_rows[results_row_count].shape, shape, RESULTS_VALUE_LEN);
	string_copy(results_rows[results_row_count].sides, calc_get_sides(), RESULTS_VALUE_LEN);
	string_copy(results_rows[results_row_count].internal_angle, calc_get_internal_angle(), RESULTS_VALUE_LEN);
	string_copy(results_rows[results_row_count].side_length, calc_get_length(), RESULTS_VALUE_LEN);
	string_copy(results_rows[results_row_count].perimeter, calc_get_perimeter(), RESULTS_VALUE_LEN);
	string_copy(results_rows[results_row_count].area, calc_get_area(), RESULTS_VALUE_LEN);

	results_row_count++;
}

/* Clear all of the stored data. */

static void results_clear_data(void)
{
	results_row_count = 0;
}

static void results_menu_selection(wimp_w window, wimp_menu *menu, wimp_selection *selection)
{
	if (menu != results_menu)
		return;

	switch (selection->items[0]) {
	case RESULTS_MENU_CLEAR:
		results_clear_data();
		break;
	}
}

static void results_plot_icon(wimp_i icon, int y0, int y1, char *text)
{
	results_icons[icon].extent.y0 = y0;
	results_icons[icon].extent.y1 = y1;

	if (results_icons[icon].flags & (wimp_ICON_TEXT | wimp_ICON_INDIRECTED))
		results_icons[icon].data.indirected_text.text = text;

	wimp_plot_icon(results_icons + icon);
}

/* Redraw the window. */

more = wimp_redraw_window(redraw);

while (more) {
	oy = redraw->box.y1 - redraw->yscroll;

	top = (oy - redraw->clip.y1) / row_height;
	if (top < 1)
		top = 1;

	bottom = ((oy - redraw->clip.y0) - 1) / row_height;
	if (bottom > RESULTS_MAX_ROWS)
		bottom = RESULTS_MAX_ROWS;

	if (bottom > results_row_count)
		bottom = results_row_count;

	for (int y = top; y <= bottom; y++) {
		icon_y1 = -(y * row_height);
		icon_y0 = icon_y1 - row_height;

		results_plot_icon(RESULTS_ICON_ROW_SHAPE, icon_y0, icon_y1, results_rows[y - 1].shape);
		results_plot_icon(RESULTS_ICON_ROW_SIDES, icon_y0, icon_y1, results_rows[y - 1].sides);
		results_plot_icon(RESULTS_ICON_ROW_INTERNAL_ANGLES, icon_y0, icon_y1, results_rows[y - 1].internal_angle);
		results_plot_icon(RESULTS_ICON_ROW_SIDE_LENGTH, icon_y0, icon_y1, results_rows[y - 1].side_length);
		results_plot_icon(RESULTS_ICON_ROW_PERIMETER, icon_y0, icon_y1, results_rows[y - 1].perimeter);
		results_plot_icon(RESULTS_ICON_ROW_AREA, icon_y0, icon_y1, results_rows[y - 1].area);
	}

	more = wimp_get_rectangle(redraw);
}

/* Window Menu. */

win_menu = menu_create("MainMenu", 4);
if (win_menu == NULL) {
	error_msgs_report_error("BadMainMenu");
	return;
}

menu_entry(win_menu, WIN_MENU_STORE_RESULT, "MainMenu0", NULL);
menu_separator(win_menu, WIN_MENU_STORE_RESULT);
menu_entry(win_menu, WIN_MENU_DECIMAL1, "MainMenu1", NULL);
menu_entry(win_menu, WIN_MENU_DECIMAL2, "MainMenu2", NULL);
menu_entry(win_menu, WIN_MENU_DECIMAL3, "MainMenu3", NULL);

/* Force the redraw of a range of rows. */

static void results_force_redraw_lines(int r0, int r1)
{
	/* Use the shape column to size the row heights. */

	int row_height = results_icons[RESULTS_ICON_TITLE_SHAPE].extent.y1 -
			results_icons[RESULTS_ICON_TITLE_SHAPE].extent.y0;

	int top = -r0 * row_height;
	int bottom = -(r1 + 1) * row_height;

	/* Get the column bounds from the Shape and Area columns. */

	int left = results_icons[RESULTS_ICON_TITLE_SHAPE].extent.x0;
	int right = results_icons[RESULTS_ICON_TITLE_AREA].extent.x1;

	/* Force the redraw of the chosen lines. */

	wimp_force_redraw(results_handle, left, bottom, right, top);
}

chapter.section:
Updating menu states


While we’re thinking about intuitiveness, there is one other small thing... RISC OS convention is that menu items are shaded when they aren’t applicable, but if we store ten results and then try to store another, the Store result menu entry is still available but will be ignored. Since c.win is already registering its win_set_menu() function as an event handler for SFLib’s menu prepare event so that it can set the ticks against the decimal place options, we could also shade Store result if we knew that the Results window was full.


To this end, we can add a public function to c.results in order to make this information available. If results_get_free_space() in  is called, it will return TRUE if there is space to add another result and FALSE otherwise.

/* Is there space to store another result? */

osbool results_get_free_space(void)
{
	return (results_row_count < RESULTS_MAX_ROWS) ? TRUE : FALSE;
}


We can then update win_set_menu() to read this information and use SFLib’s menus_shade_entry() function to update the menu entry as required – this is a much less contrived example of this function’s use than when we introduced it back in !

static void win_set_menu(wimp_w w, wimp_menu *menu, wimp_pointer *pointer)
{
	if (menu != win_menu)
		return;

	int places = calc_get_places();

	menus_tick_entry(win_menu, WIN_MENU_DECIMAL1, places == 1);
	menus_tick_entry(win_menu, WIN_MENU_DECIMAL2, places == 2);
	menus_tick_entry(win_menu, WIN_MENU_DECIMAL3, places == 3);

	osbool free_space = results_get_free_space();

	menus_shade_entry(win_menu, WIN_MENU_STORE_RESULT, !free_space);
}


To do the same thing for the Clear contents entry in the Results window menu, we can create a new results_set_menu() in c.results as seen in . This shades the entry if results_row_count is zero, indicating that there are no results to be cleared.

/* Menu Prepare event handler. */

static void results_set_menu(wimp_w w, wimp_menu *menu, wimp_pointer *pointer)
{
	if (menu != results_menu)
		return;

	menus_shade_entry(results_menu, RESULTS_MENU_CLEAR, (results_row_count == 0) ? TRUE : FALSE);
}


This new function can be registered as a menu prepare event handler from results_initialise().

event_add_window_menu_prepare(results_handle, results_set_menu);


We should now find that the menu entries relating to the results shade out when appropriate, as seen in . It's a small thing, but it follows the convention and saves the user wondering why a menu entry doesn’t respond.




The full application code with these changes included can be found in .

 (in the context of a useless application)


We now have a fully functional Results window (at least in the context of a useless application), but before moving on from window redraw we should note that we aren’t restricted to using Wimp_PlotIcon to draw content in our windows. It’s a very useful call, because it makes it easy to keep a standard ‘look and feel’ to our window contents, but any graphics calls are available to us from within the redraw loop. In the next chapter, we will take a short diversion to look at some of these.
